Íme egy teljes, önálló index.html fájl, amely tartalmazza a Hex Színkód Kinyerő webalkalmazást, beágyazott CSSsel és JavaScripttel. Ez a változat mobilbarát, magyar nyelvű, modern felületet biztosít, és lehetővé teszi képekből a domináns színek kinyerését, azok HEX kódjának másolását, valamint a színek exportját.

html
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
  <title>Hex Színkód Kinyerő</title>
  <style>
    body {
      background: #0a0d1a;
      color: #fff;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      margin: 0;
      padding: 0;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    h1 {
      margin-top: 32px;
      margin-bottom: 16px;
      font-size: 2rem;
      background: linear-gradient(to right, #0080FB, #121DFB, #131AFB);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      text-align: center;
      text-shadow: 0 2px 10px rgba(19, 26, 251, 0.3);
    }
    .container {
      background: rgba(12, 13, 30, 0.95);
      border-radius: 18px;
      padding: 28px 18px 24px 18px;
      margin: 24px 0;
      box-shadow: 0 8px 24px rgba(0,0,0,0.25);
      max-width: 420px;
      width: 100%;
    }
    .upload-area {
      border: 2px dashed #121DFB;
      border-radius: 12px;
      padding: 32px 10px;
      text-align: center;
      cursor: pointer;
      background: rgba(255,255,255,0.04);
      transition: background .2s;
      margin-bottom: 16px;
    }
    .upload-area:hover {
      background: rgba(18,29,251,0.08);
    }
    .upload-area input {
      display: none;
    }
    #imagePreview {
      max-width: 100%;
      max-height: 220px;
      display: block;
      margin: 12px auto 10px auto;
      border-radius: 10px;
      box-shadow: 0 4px 20px rgba(0,0,0,0.15);
    }
    .button {
      background: linear-gradient(to right, #00A0FB, #0071FB, #111EFB);
      color: #fff;
      border: none;
      padding: 12px 28px;
      font-size: 1rem;
      border-radius: 10px;
      margin: 10px 0 16px 0;
      font-weight: 600;
      cursor: pointer;
      width: 100%;
      transition: background .2s, transform .2s;
      box-shadow: 0 4px 14px rgba(6, 58, 251, 0.18);
    }
    .button:hover { background: #121DFB; transform: translateY(-2px);}
    .colors {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 10px;
      justify-content: center;
    }
    .color-item {
      display: flex;
      flex-direction: column;
      align-items: center;
      margin-bottom: 8px;
    }
    .color-box {
      width: 54px;
      height: 54px;
      border-radius: 8px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.18);
      margin-bottom: 6px;
      border: 2px solid #121DFB;
      cursor: pointer;
      position: relative;
    }
    .color-code {
      font-size: 0.97rem;
      background: rgba(255,255,255,0.09);
      border-radius: 5px;
      padding: 2px 8px;
      font-family: SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      user-select: all;
      cursor: pointer;
      color: #fff;
    }
    .copy-message {
      color: #00C400;
      font-size: 0.92rem;
      margin-top: 4px;
      text-align: center;
      min-height: 18px;
    }
    .export-section {
      margin-top: 20px;
      text-align: center;
    }
    .export-section textarea {
      width: 96%;
      min-height: 48px;
      font-size: 0.97rem;
      border-radius: 8px;
      border: 1px solid #121DFB;
      padding: 8px;
      background: rgba(255,255,255,0.08);
      color: #fff;
      font-family: SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      margin-top: 7px;
      resize: vertical;
    }
    .export-section label {
      font-size: 0.95rem;
      color: #b7c6ff;
      margin-top: 10px;
      display: block;
    }
    @media (max-width: 600px) {
      .container { max-width: 98vw; padding: 10px 3vw 18px 3vw; }
      .color-box { width: 44px; height: 44px; }
    }
  </style>
</head>
<body>
  <h1>Hex Színkód Kinyerő</h1>
  <div class="container">
    <div class="upload-area" id="uploadArea">
      <div style="font-size:2.3rem;">🎨</div>
      <div>Tölts fel egy képet, vagy kattints ide!</div>
      <input type="file" id="fileInput" accept="image/*">
    </div>
    <img id="imagePreview" src="" alt="Előnézet" style="display:none;">
    <button class="button" id="extractBtn" style="display:none;">Színek kinyerése</button>
    <div class="copy-message" id="copyMsg"></div>
    <div class="colors" id="colors"></div>
    <div class="export-section" id="exportSection" style="display:none;">
      <label for="cssVars">CSS változók:</label>
      <textarea id="cssVars" readonly></textarea>
      <label for="jsonExport">JSON:</label>
      <textarea id="jsonExport" readonly></textarea>
    </div>
  </div>
  <script>
    // DOM elemek
    const uploadArea = document.getElementById('uploadArea');
    const fileInput = document.getElementById('fileInput');
    const imagePreview = document.getElementById('imagePreview');
    const extractBtn = document.getElementById('extractBtn');
    const colorsDiv = document.getElementById('colors');
    const copyMsg = document.getElementById('copyMsg');
    const exportSection = document.getElementById('exportSection');
    const cssVars = document.getElementById('cssVars');
    const jsonExport = document.getElementById('jsonExport');

    let imgDataUrl = '';

    // Kép feltöltés
    uploadArea.addEventListener('click', () => fileInput.click());
    uploadArea.addEventListener('dragover', e => {
      e.preventDefault(); uploadArea.style.background = 'rgba(18,29,251,0.16)';
    });
    uploadArea.addEventListener('dragleave', e => {
      e.preventDefault(); uploadArea.style.background = '';
    });
    uploadArea.addEventListener('drop', e => {
      e.preventDefault();
      uploadArea.style.background = '';
      if (e.dataTransfer.files && e.dataTransfer.files[0]) {
        handleFile(e.dataTransfer.files[0]);
      }
    });
    fileInput.addEventListener('change', e => {
      if (e.target.files && e.target.files[0]) {
        handleFile(e.target.files[0]);
      }
    });

    function handleFile(file) {
      if (!file.type.startsWith('image/')) return;
      const reader = new FileReader();
      reader.onload = e => {
        imgDataUrl = e.target.result;
        imagePreview.src = imgDataUrl;
        imagePreview.style.display = 'block';
        extractBtn.style.display = 'block';
        colorsDiv.innerHTML = '';
        exportSection.style.display = 'none';
        copyMsg.textContent = '';
      };
      reader.readAsDataURL(file);
    }

    // Színek kinyerése
    extractBtn.addEventListener('click', () => {
      if (!imgDataUrl) return;
      copyMsg.textContent = 'Színek feldolgozása...';
      setTimeout(() => extractColors(imgDataUrl), 100);
    });

    function extractColors(imgSrc) {
      const img = new window.Image();
      img.crossOrigin = 'Anonymous';
      img.onload = () => {
        // Lekicsinyítjük a képet gyors feldolgozáshoz
        const maxDim = 200;
        let w = img.width, h = img.height;
        if (w > maxDim || h > maxDim) {
          if (w > h) { h = Math.round(h * maxDim / w); w = maxDim; }
          else { w = Math.round(w * maxDim / h); h = maxDim; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        const data = ctx.getImageData(0, 0, w, h).data;
        // Színek számlálása
        const colorCount = {};
        for (let i = 0; i < data.length; i += 4) {
          const [r,g,b,a] = [data[i], data[i+1], data[i+2], data[i+3]];
          if (a < 128) continue; // Átlátszó pixelek kihagyása
          // Kvantálás: 16-os lépésköz (kb. 4096 szín)
          const qr = Math.round(r/16)*16, qg = Math.round(g/16)*16, qb = Math.round(b/16)*16;
          const hex = rgbToHex(qr,qg,qb);
          colorCount[hex] = (colorCount[hex]||0)+1;
        }
        // Domináns színek kiválasztása
        const sorted = Object.entries(colorCount)
          .sort((a,b)=>b[1]-a[1])
          .slice(0,10)
          .map(x=>x[0]);
        showColors(sorted);
        showExport(sorted);
        copyMsg.textContent = '';
      };
      img.src = imgSrc;
    }

    function rgbToHex(r,g,b) {
      return "#" + [r,g,b].map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase();
    }

    function showColors(hexList) {
      colorsDiv.innerHTML = '';
      hexList.forEach(hex => {
        const item = document.createElement('div');
        item.className = 'color-item';
        const box = document.createElement('div');
        box.className = 'color-box';
        box.style.background = hex;
        box.title = hex;
        box.addEventListener('click', () => copyColor(hex));
        const code = document.createElement('div');
        code.className = 'color-code';
        code.textContent = hex;
        code.addEventListener('click', () => copyColor(hex));
        item.appendChild(box);
        item.appendChild(code);
        colorsDiv.appendChild(item);
      });
    }

    function copyColor(hex) {
      navigator.clipboard.writeText(hex).then(() => {
        copyMsg.textContent = `Kimásolva: ${hex}`;
        setTimeout(()=>copyMsg.textContent='', 1500);
      });
    }

    function showExport(hexList) {
      exportSection.style.display = '';
      cssVars.value = hexList.map((h,i)=>`--szin${i+1}: ${h};`).join('\n');
      jsonExport.value = JSON.stringify(hexList, null, 2);
    }
  </script>
</body>
</html>


Használat:  
 Tölts fel egy képet, majd kattints a "Színek kinyerése" gombra.
 A 10 leggyakoribb szín HEX kódja megjelenik, kattintással másolható.
 Alul a színek exportálhatók CSS változóként vagy JSONként.

Ez a kód teljesen önálló, nem igényel külső könyvtárakat vagy szervert.
